using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.AccessControl;
using System.Security.Principal;
using System.Xml;
using System.Xml.Serialization;
using Microsoft.Win32;
namespace OpenAntiLag {
 public sealed class DnsConfig {public string Adapter;public int Family;public bool Automatic;public string[] Servers=new string[0];public DnsConfig Copy(){return new DnsConfig {Adapter=Adapter,Family=Family,Automatic=Automatic,Servers=(string[])Servers.Clone()};}public bool Same(DnsConfig other){return other!=null&&Adapter==other.Adapter&&Family==other.Family&&Automatic==other.Automatic&&(Automatic||Servers.SequenceEqual(other.Servers));}}
 public sealed class QosPolicy {public string Name,Path,Fingerprint;public long BitsPerSecond;public int Dscp=-1;public bool Same(QosPolicy value){return value!=null&&Name==value.Name&&String.Equals(Path,value.Path,StringComparison.OrdinalIgnoreCase)&&BitsPerSecond==value.BitsPerSecond&&Dscp==value.Dscp&&(Fingerprint==null||Fingerprint==value.Fingerprint);}}
 public sealed class DnsJournal {public DnsConfig Original,Applied;public bool Attempted;}
 public sealed class QosJournal {public QosPolicy Applied;public bool Attempted;}
 public sealed class NetworkState {public int Version=1;public string OwnerSid;public List<DnsJournal> Dns=new List<DnsJournal>();public List<QosJournal> Qos=new List<QosJournal>();}
 public interface INetworkStateStore {NetworkState Load();void Save(NetworkState state);}
 public static class NetworkValidation {
  public static void Dns(DnsConfig value){Guid id;if(value==null||!Guid.TryParse(value.Adapter,out id)||(value.Family!=4&&value.Family!=6)||value.Servers==null)throw new InvalidDataException("Повреждён снимок DNS");if(value.Automatic){if(value.Servers.Length!=0)throw new InvalidDataException("DHCP DNS содержит static override");}else NetworkInput.Servers(String.Join(",",value.Servers),value.Family);}
  public static void Qos(QosPolicy value){Guid id;if(value==null||value.Name==null||!value.Name.StartsWith("OpenAntiLag-",StringComparison.Ordinal)||!Guid.TryParse(value.Name.Substring(12),out id)||GameConnections.IsProtected(value.Path)||(value.Fingerprint!=null&&value.Fingerprint.Length>16384)||value.BitsPerSecond%8!=0||value.BitsPerSecond<0||value.BitsPerSecond>1000000000000L||value.Dscp< -1||value.Dscp>63||(value.BitsPerSecond==0&&value.Dscp<0))throw new InvalidDataException("Небезопасная политика QoS");}
  public static void State(NetworkState state){if(state==null||state.Version!=1||state.Dns==null||state.Qos==null||state.Dns.Count>64||state.Qos.Count>64)throw new InvalidDataException("Повреждён сетевой журнал. Диагностика доступна, запись запрещена.");if((state.Dns.Count>0||state.Qos.Count>0)&&String.IsNullOrEmpty(state.OwnerSid))throw new InvalidDataException("Нет владельца сетевого журнала");foreach(var d in state.Dns){Dns(d.Original);Dns(d.Applied);if(d.Original.Adapter!=d.Applied.Adapter||d.Original.Family!=d.Applied.Family)throw new InvalidDataException("Снимки разных адаптеров");}foreach(var q in state.Qos)Qos(q.Applied);if(state.Dns.GroupBy(d=>d.Applied.Adapter+":"+d.Applied.Family).Any(g=>g.Count()>1)||state.Qos.GroupBy(q=>q.Applied.Name).Any(g=>g.Count()>1))throw new InvalidDataException("Дубли в сетевом журнале");}
 }
 public sealed class NetworkStateStore:INetworkStateStore {
  const string Key=@"SOFTWARE\OpenAntiLag\NetworkProfile";
  public static NetworkState Parse(string xml){if(xml.Length>512*1024)throw new InvalidDataException("Слишком большой сетевой журнал");using(var reader=XmlReader.Create(new StringReader(xml),new XmlReaderSettings {DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null})){var state=(NetworkState)new XmlSerializer(typeof(NetworkState)).Deserialize(reader);NetworkValidation.State(state);return state;}}
  public NetworkState Load(){using(var key=Registry.LocalMachine.OpenSubKey(Key)){if(key==null||key.GetValue("Journal")==null)return new NetworkState();if(key.GetValueKind("Journal")!=RegistryValueKind.String)throw new InvalidDataException("Тип сетевого журнала повреждён");return Parse((string)key.GetValue("Journal"));}}
  public void Save(NetworkState state){NetworkValidation.State(state);var acl=new RegistrySecurity();acl.SetAccessRuleProtection(true,false);foreach(var sid in new[]{WellKnownSidType.BuiltinAdministratorsSid,WellKnownSidType.LocalSystemSid})acl.AddAccessRule(new RegistryAccessRule(new SecurityIdentifier(sid,null),RegistryRights.FullControl,InheritanceFlags.ContainerInherit,PropagationFlags.None,AccessControlType.Allow));acl.AddAccessRule(new RegistryAccessRule(new SecurityIdentifier(WellKnownSidType.BuiltinUsersSid,null),RegistryRights.ReadKey,InheritanceFlags.ContainerInherit,PropagationFlags.None,AccessControlType.Allow));using(var writer=new StringWriter()){new XmlSerializer(typeof(NetworkState)).Serialize(writer,state);using(var key=Registry.LocalMachine.CreateSubKey(Key,RegistryKeyPermissionCheck.ReadWriteSubTree,acl)){var old=key.GetValue("Journal") as string;if(old!=null)key.SetValue("PreviousJournal",old,RegistryValueKind.String);key.SetValue("Journal",writer.ToString(),RegistryValueKind.String);key.Flush();}}}
 }
 public interface INetworkConfigurationHost {void Preflight(string feature);DnsConfig ReadDns(string adapter,int family);void WriteDns(DnsConfig config);QosPolicy ReadQos(string name);void CreateQos(QosPolicy policy);void DeleteQos(string name);}
 public sealed class NetworkController {
  readonly INetworkConfigurationHost host;readonly INetworkStateStore store;readonly string owner;
  public NetworkState State {get;private set;}
  public NetworkController(INetworkConfigurationHost host,INetworkStateStore store,string owner){this.host=host;this.store=store;this.owner=owner;State=store.Load();NetworkValidation.State(State);}
  void CheckOwner(){if((State.Dns.Count>0||State.Qos.Count>0)&&State.OwnerSid!=owner)throw new InvalidOperationException("Сетевые изменения принадлежат другой учётной записи. Восстановите их из неё.");}
  void Save(){store.Save(State);}
  public void ApplyDns(DnsConfig requested){NetworkValidation.Dns(requested);CheckOwner();host.Preflight("DNS");if(State.Dns.Any(d=>d.Applied.Adapter==requested.Adapter&&d.Applied.Family==requested.Family))throw new InvalidOperationException("Сначала восстановите DNS этого адаптера/семейства.");var original=host.ReadDns(requested.Adapter,requested.Family);NetworkValidation.Dns(original);if(original.Same(requested))return;var entry=new DnsJournal {Original=original.Copy(),Applied=requested.Copy()};State.OwnerSid=owner;State.Dns.Add(entry);Save();try{entry.Attempted=true;Save();host.WriteDns(requested);if(!host.ReadDns(requested.Adapter,requested.Family).Same(requested))throw new IOException("Windows не подтвердила DNS");}catch(Exception error){try{RestoreDnsEntry(entry);}catch(Exception recovery){throw new IOException(error.Message+" Восстановление DNS не завершено: "+recovery.Message,error);}throw;}}
  public void ApplyQos(QosPolicy requested){NetworkValidation.Qos(requested);CheckOwner();host.Preflight("QoS");if(State.Qos.Any(q=>String.Equals(q.Applied.Path,requested.Path,StringComparison.OrdinalIgnoreCase)))throw new InvalidOperationException("Сначала восстановите политику этого EXE.");if(host.ReadQos(requested.Name)!=null)throw new InvalidOperationException("Такое имя политики уже существует");var entry=new QosJournal {Applied=requested};State.OwnerSid=owner;State.Qos.Add(entry);Save();try{entry.Attempted=true;Save();host.CreateQos(requested);var actual=host.ReadQos(requested.Name);if(!requested.Same(actual))throw new IOException("Windows не подтвердила QoS");entry.Applied.Fingerprint=actual.Fingerprint;Save();}catch(Exception error){try{RestoreQosEntry(entry);}catch(Exception recovery){throw new IOException(error.Message+" Восстановление QoS не завершено: "+recovery.Message,error);}throw;}}
  void RestoreDnsEntry(DnsJournal entry){if(entry.Attempted){var actual=host.ReadDns(entry.Applied.Adapter,entry.Applied.Family);if(actual.Same(entry.Applied)){host.Preflight("DNS");host.WriteDns(entry.Original);if(!host.ReadDns(entry.Original.Adapter,entry.Original.Family).Same(entry.Original))throw new IOException("DNS не восстановлен");}else if(!actual.Same(entry.Original))throw new IOException("DNS изменён извне или частично. Автоматический откат не перезаписывает его; журнал сохранён.");}State.Dns.Remove(entry);Save();}
  void RestoreQosEntry(QosJournal entry){if(entry.Attempted){var actual=host.ReadQos(entry.Applied.Name);if(actual!=null){if(entry.Applied.Fingerprint==null&&actual.Fingerprint!=null)throw new IOException("Не завершена фиксация созданной QoS. Автоматическое удаление без подтверждённого снимка запрещено; журнал сохранён.");if(!entry.Applied.Same(actual))throw new IOException("Политика QoS изменена извне. Она сохранена вместе с журналом.");host.Preflight("QoS");host.DeleteQos(entry.Applied.Name);if(host.ReadQos(entry.Applied.Name)!=null)throw new IOException("QoS не удалена");}}State.Qos.Remove(entry);Save();}
  public void Restore(string feature){CheckOwner();var errors=new List<string>();if(feature=="DNS")foreach(var entry in State.Dns.ToArray())try{RestoreDnsEntry(entry);}catch(Exception e){errors.Add(e.Message);}else if(feature=="QoS")foreach(var entry in State.Qos.ToArray())try{RestoreQosEntry(entry);}catch(Exception e){errors.Add(e.Message);}else throw new ArgumentException("Неизвестная операция восстановления");if(errors.Count>0)throw new IOException(String.Join("\n",errors));}
 }
}
